<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Holder\TrustedClientLogoUriAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientLogoUriAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TrustedClientLogoUriAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getLogoUri returns null on a freshly created holder.
     */
    public function testLogoUriNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientLogoUriAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isLogoUriAssigned());
        $this->assertNull($holder->getLogoUri());
    }
}
class ImplWithTrustedClientLogoUriAttributeHolderUnitTest
{
    use TrustedClientLogoUriAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedLogoUriRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultLogoUri();
    }
}
